dren":[{"text":"_____________________________"}]},{"type":"p","children":[{"text":"Signature / date","italic":true}]}]}]}]'::jsonb, html='<!DOCTYPE html><html><head><meta charset="utf-8"><style>* { box-sizing: border-box; }
body { font-family: Arial, Helvetica, sans-serif; font-size: 11px; color: #1a1a1a; margin: 0; padding: 0; line-height: 1.45; }
h1 { font-size: 16px; font-weight: 700; margin: 0 0 6px; }
h2 { font-size: 14px; font-weight: 700; margin: 10px 0 4px; }
h3 { font-size: 12px; font-weight: 700; text-transform: none; margin: 8px 0 3px; }
p { margin: 4px 0; }
ul, ol { margin: 4px 0; padding-left: 20px; }
li { margin: 1px 0; }
strong { font-weight: 700; } em { font-style: italic; } u { text-decoration: underline; }
a { color: #1a1a1a; text-decoration: underline; }
hr { border: 0; border-top: 1px solid #b4b4b4; margin: 10px 0; }
img { max-width: 100%; }
/* Line-items table (repeating rows) — the seeded look */
table.items { width: 100%; border-collapse: collapse; margin: 10px 0; }
table.items th { background: #3c525c; color: #fff; text-align: left; padding: 5px 6px; font-size: 10px; }
table.items td { padding: 4px 6px; border-bottom: 1px solid #e2e2e2; font-size: 10px; vertical-align: top; }
table.items .num { text-align: right; }
/* User rich-text table */
table.rt-table { width: 100%; border-collapse: collapse; margin: 8px 0; table-layout: fixed; }
table.rt-table td, table.rt-table th { border: 1px solid #cbd5e1; padding: 4px 6px; font-size: 10px; vertical-align: top; }
table.rt-table th { background: #f1f5f9; font-weight: 600; text-align: left; }
.num { text-align: right; }
/* Side-by-side columns (Seller | Buyer) */
.doc-cols { display: flex; gap: 24px; }
.doc-col { flex: 1; }
.doc-col > p { margin: 2px 0; }
/* Callout / bordered box (payment details, highlights) */
.callout-box { border: 1px solid #3c525c; border-radius: 4px; padding: 10px 12px; background: #f4f7f8; margin: 8px 0; }
.callout-box > p { margin: 2px 0; }
.callout-box h3 { margin-top: 0; }
/* Letterhead + footer */
.doc-logo { margin-bottom: 10px; }
.doc-logo img { max-height: 64px; }
.doc-footer { position: fixed; bottom: 4mm; left: 0; right: 0; text-align: center; font-size: 9px; color: #8a8a8a; }
@page { size: A4; margin: 12mm 12mm 12mm 12mm; }
body { padding: 0 0 0 0; }
</style></head><body><div class="doc-cols"><div class="doc-col"><h2>{{seller.name}}</h2></div><div class="doc-col"><h2 style="text-align:right">{{docTitle}}</h2></div></div><p style="text-align:right">{{docNumber}} · Deal {{dealCode}} · {{fmtDate docDate}}</p><hr><div class="doc-cols"><div class="doc-col"><h3>Seller</h3><p>{{seller.name}}</p>{{#if seller.address}}<p>{{seller.address}}</p>{{/if}}{{#if seller.regNo}}<p>Reg. No: {{seller.regNo}}</p>{{/if}}{{#if seller.vatNo}}<p>VAT: {{seller.vatNo}}</p>{{/if}}{{#if seller.email}}<p>{{seller.email}}</p>{{/if}}{{#if seller.phone}}<p>{{seller.phone}}</p>{{/if}}{{#if seller.bankName}}<p>Bank: {{seller.bankName}}</p>{{/if}}{{#if seller.bankAccount}}<p>Account: {{seller.bankAccount}}</p>{{/if}}{{#if seller.bankSwift}}<p>SWIFT: {{seller.bankSwift}}</p>{{/if}}</div><div class="doc-col"><h3>Buyer</h3><p>{{buyer.name}}</p>{{#if buyer.address}}<p>{{buyer.address}}</p>{{/if}}{{#if buyer.regNo}}<p>Reg. No: {{buyer.regNo}}</p>{{/if}}{{#if buyer.vatNo}}<p>VAT: {{buyer.vatNo}}</p>{{/if}}{{#if buyer.email}}<p>{{buyer.email}}</p>{{/if}}{{#if buyer.phone}}<p>{{buyer.phone}}</p>{{/if}}</div></div><h3>1. Subject of the contract</h3><p>The Seller sells and the Buyer buys the timber goods specified in the schedule below, on the terms set out in this contract.</p><h3>2. Price and total value</h3><p>Prices are stated in {{currency}} per the schedule. The total contract value is {{moneyCur totals.totalCents}} including VAT at {{totals.vatRate}}% ({{money totals.vatCents}} {{currency}}). In words: {{totals.amountInWords}}.</p><h3>3. Payment terms</h3>{{#if paymentTerms}}<p>Terms: {{paymentTerms}}</p>{{/if}}<h3>4. Delivery</h3>{{#if incoterms}}<p>Incoterms: {{incoterms}}</p>{{/if}}{{#if deliveryTerms}}<p>Delivery: {{deliveryTerms}}</p>{{/if}}{{#if deliveryDeadline}}<p>Deadline: {{deliveryDeadline}}</p>{{/if}}<h3>5. Schedule of goods</h3><table class="items"><thead><tr><th class="num">#</th><th>Description</th><th>Dimensions (mm)</th><th class="num">Pcs</th><th class="num">m³</th><th class="num">Unit price</th><th class="num">Total</th></tr></thead><tbody>{{#each lineItems}}<tr><td class="num">{{lineNo}}</td><td>{{description}}</td><td>{{dimensions}}</td><td class="num">{{pieces}}</td><td class="num">{{fmtM3 volumeM3}}</td><td class="num">{{money unitPriceCents}}</td><td class="num">{{money lineTotalCents}}</td></tr>{{/each}}</tbody></table><p style="text-align:right">Subtotal: {{money totals.subtotalCents}} {{currency}}</p><p style="text-align:right">VAT ({{totals.vatRate}}%): {{money totals.vatCents}} {{currency}}</p><p style="text-align:right"><strong>Total: </strong>{{moneyCur totals.totalCents}}</p><h3>6. Additional terms</h3>{{#if notes}}<p>{{notes}}</p>{{/if}}<div class="doc-cols"><div class="doc-col"><h3>Seller</h3><p>{{seller.name}}</p><p></p><p>_____________________________</p><p><em>Signature / date</em></p></div><div class="doc-col"><h3>Buyer</h3><p>{{buyer.name}}</p><p></p><p>_____________________________</p><p><em>Signature / date</em></p></div></div></body></html>', page_settings=NULL WHERE doc_type='contract' AND is_default;

