table.rt-table td, table.rt-table th { border: 1px solid #cbd5e1; padding: 4px 6px; font-size: 10px; vertical-align: top; }
table.rt-table th { background: #f1f5f9; font-weight: 600; text-align: left; }
.num { text-align: right; }
/* Side-by-side columns (Seller | Buyer) */
.doc-cols { display: flex; gap: 24px; }
.doc-col { flex: 1; }
.doc-col > p { margin: 2px 0; }
/* Callout / bordered box (payment details, highlights) */
.callout-box { border: 1px solid #3c525c; border-radius: 4px; padding: 10px 12px; background: #f4f7f8; margin: 8px 0; }
.callout-box > p { margin: 2px 0; }
.callout-box h3 { margin-top: 0; }
/* Letterhead + footer */
.doc-logo { margin-bottom: 10px; }
.doc-logo img { max-height: 64px; }
.doc-footer { position: fixed; bottom: 4mm; left: 0; right: 0; text-align: center; font-size: 9px; color: #8a8a8a; }
@page { size: A4; margin: 12mm 12mm 12mm 12mm; }
body { padding: 0 0 0 0; }
</style></head><body><div class="doc-cols"><div class="doc-col"><h2>{{seller.name}}</h2></div><div class="doc-col"><h2 style="text-align:right">{{docTitle}}</h2></div></div><p style="text-align:right">{{docNumber}} · Deal {{dealCode}} · {{fmtDate docDate}}</p><hr><div class="doc-cols"><div class="doc-col"><h3>Sender</h3><p>{{seller.name}}</p>{{#if seller.address}}<p>{{seller.address}}</p>{{/if}}{{#if seller.regNo}}<p>Reg. No: {{seller.regNo}}</p>{{/if}}{{#if seller.vatNo}}<p>VAT: {{seller.vatNo}}</p>{{/if}}{{#if seller.email}}<p>{{seller.email}}</p>{{/if}}{{#if seller.phone}}<p>{{seller.phone}}</p>{{/if}}</div><div class="doc-col"><h3>Consignee</h3><p>{{buyer.name}}</p>{{#if buyer.address}}<p>{{buyer.address}}</p>{{/if}}{{#if buyer.regNo}}<p>Reg. No: {{buyer.regNo}}</p>{{/if}}{{#if buyer.vatNo}}<p>VAT: {{buyer.vatNo}}</p>{{/if}}{{#if buyer.email}}<p>{{buyer.email}}</p>{{/if}}{{#if buyer.phone}}<p>{{buyer.phone}}</p>{{/if}}</div></div><h3>Terms</h3>{{#if incoterms}}<p>Incoterms: {{incoterms}}</p>{{/if}}{{#if paymentTerms}}<p>Payment: {{paymentTerms}}</p>{{/if}}{{#if deliveryTerms}}<p>Delivery: {{deliveryTerms}}</p>{{/if}}{{#if deliveryDeadline}}<p>Deadline: {{deliveryDeadline}}</p>{{/if}}<h3>Goods</h3><table class="items"><thead><tr><th class="num">#</th><th>Description</th><th>Dimensions (mm)</th><th class="num">Pcs</th><th class="num">m³</th></tr></thead><tbody>{{#each lineItems}}<tr><td class="num">{{lineNo}}</td><td>{{description}}</td><td>{{dimensions}}</td><td class="num">{{pieces}}</td><td class="num">{{fmtM3 volumeM3}}</td></tr>{{/each}}</tbody></table><p style="text-align:right">Total volume: {{fmtM3 totals.totalVolumeM3}} m³</p><p style="text-align:right">Subtotal: {{money totals.subtotalCents}} {{currency}}</p><p style="text-align:right">VAT ({{totals.vatRate}}%): {{money totals.vatCents}} {{currency}}</p><p style="text-align:right"><strong>Total: </strong>{{moneyCur totals.totalCents}}</p><h3>Notes</h3>{{#if notes}}<p>{{notes}}</p>{{/if}}<div class="doc-cols"><div class="doc-col"><h3>Sender</h3><p>{{seller.name}}</p><p></p><p>_____________________________</p><p><em>Signature / date</em></p></div><div class="doc-col"><h3>Carrier</h3><p>{{buyer.name}}</p><p></p><p>_____________________________</p><p><em>Signature / date</em></p></div></div></body></html>', page_settings=NULL WHERE doc_type='cmr' AND is_default;

